340	  if (currentMilestone >= dream.milestones.length) return; // 已全部完成
341	
342	  var milestone = dream.milestones[currentMilestone];
343	  if (!milestone) return;
344	
345	  // 检查条件
346	  if (milestone.condition(state)) {
347	    state.flags._dreamMilestone = currentMilestone + 1;
348	    // 防重复触发
349	    var flagKey = "_dreamMilestoneShown_" + milestone.id;
350	    if (!state.flags[flagKey]) {
351	      state.flags[flagKey] = true;
352	      StateManager.addMessage(
353	        dream.icon +
354	          " 【梦想里程碑：" +
355	          milestone.title +
356	          "】\n" +
357	          milestone.story,
358	        "event",
359	      );
360	    }
361	  }
362	}
